input.command:
gh api graphql -f query='
{
  repository(owner:"ZimmermannAU", name:"zimmermann-pwa") {
    pullRequest(number:57) {
      reviewThreads(last:20) {
        nodes {
          isResolved
          isOutdated
          path
          line
          comments(first:10){nodes{author{login} body}}
        }
      }
    }
  }
}' 2>&1 | python3 -c "
import json,sys
d=json.load(sys.stdin)
th=d['data']['repository']['pullRequest']['reviewThreads']['nodes']
print('total threads:',len(th))
for t in th:
    if t['isResolved']: continue
    print('---- UNRESOLVED', t['path'], t['line'], 'outdated:',t['isOutdated'])
    for c in t['comments']['nodes']:
        print('   ',c['author']['login'],':',c['body'][:600].replace(chr(10),' '))
"

